(1, 'The Kingdom of Azeroth', 'Elwynn''s fields to the scorched Blasted Lands.', 0, 0, 0, 'Interface\\Icons\\INV_BannerPVP_02'),
(2, 'Khaz Modan', 'The dwarven mountains, from Dun Morogh to the Burning Steppes.', 0, 0, 1, 'Interface\\Icons\\INV_Hammer_Unique_Sulfuras'),
(3, 'Lordaeron', 'The fallen northern kingdom, from Tirisfal to the plague-blighted east.', 0, 0, 2, 'Interface\\Icons\\Spell_Shadow_RaiseDead'),
(4, 'Quel''Thalas', 'The forests of the high elves.', 0, 0, 3, 'Interface\\Icons\\Spell_Holy_MindVision'),
