(6, 'Northern Kalimdor', 'The ancient forests of the night elves, from Teldrassil to Mount Hyjal.', 0, 0, 5, 'Interface\\Icons\\Ability_Druid_Dreamstate'),
(7, 'The Heart of Kalimdor', 'Durotar and Mulgore, the Barrens and the lands around them.', 0, 0, 6, 'Interface\\Icons\\INV_Misc_Head_Tauren_01'),
(8, 'Southern Kalimdor', 'Feralas, Tanaris, Un''Goro and the sands of Silithus.', 0, 0, 7, 'Interface\\Icons\\INV_Misc_Desecrated_PlateHelm'),
(9, 'Eastern Kingdoms', 'Every zone of the Eastern Kingdoms.', 1, 0, 8, 'Interface\\Icons\\INV_Misc_Map_01'),
